  1	// Emits Orca's platforms.linux keybinding overrides: every action's macOS
  2	// default, with Mod (Cmd there, Ctrl here) spelled Cmd, which Orca binds to
  3	// Super on Linux. See orca.nix.
  4	//
  5	//   node orca-mac-keybindings.js <app>/out/shared <hyprland-chords.json>
  6	//
  7	// Uses Orca's own keybinding module (out/shared/keybindings.js, the stable
  8	// facade its comment promises) for the definitions, normalisation and the
  9	// conflict check, so a version bump regenerates the table instead of
 10	// silently drifting from it.
 11	const fs = require('fs');
 12	const path = require('path');
 13	
 14	const [shared, chordsFile] = process.argv.slice(2);
 15	const kb = require(path.resolve(shared, 'keybindings.js'));
 16	
 17	// Chords Hyprland binds never reach the window. "SUPER + SHIFT + W" ->
 18	// "Cmd+Shift+W", Hyprland's modifier and keysym aliases included (keysyms
 19	// case-insensitively, as Hyprland reads them). Mouse, switch and media binds,
 20	// and the few keys Orca has no chord for (NO_CHORD), are skipped. Anything
 21	// else that does not translate fails the build: an unknown name may be an
 22	// Orca chord spelled another way, and guessing "harmless" ships a dead key.
 23	const MODS = {
 24	  SUPER: 'Cmd', WIN: 'Cmd', LOGO: 'Cmd', MOD4: 'Cmd', META: 'Cmd',
 25	  CTRL: 'Ctrl', CONTROL: 'Ctrl',
 26	  ALT: 'Alt', MOD1: 'Alt',
 27	  SHIFT: 'Shift',
 28	};
 29	const KEYS = {
 30	  return: 'Enter', left: 'ArrowLeft', right: 'ArrowRight', up: 'ArrowUp', down: 'ArrowDown',
 31	  grave: 'Backquote', apostrophe: 'Quote',
 32	  prior: 'PageUp', next: 'PageDown', page_up: 'PageUp', page_down: 'PageDown',
 33	  kp_add: 'NumpadAdd', kp_subtract: 'NumpadSubtract',
 34	};
 35	const NO_CHORD = new Set(['print', 'scroll_lock', 'pause', 'sys_req', 'menu']);
 36	// Hyprland matches a bind on the unshifted keysym, but Orca matches the key
 37	// the press produced: Shift+= arrives as "+", which Orca names Plus, and
 38	// Shift+- as Underscore. Every other punctuation key Orca matches by its
 39	// unshifted name under Shift (probed against keybindingMatchesInput).
 40	const SHIFTED = { Equal: 'Plus', Minus: 'Underscore' };
 41	const taken = new Set();
 42	for (const chord of JSON.parse(fs.readFileSync(chordsFile, 'utf8'))) {
 43	  if (typeof chord !== 'string') throw new Error(`Hyprland bind with a non-string key: ${JSON.stringify(chord)}`);
 44	  const parts = chord.split('+').map((s) => s.trim());
 45	  const key = parts.pop();
 46	  if (/^(mouse[:_]|xf86)/i.test(key) || chord.startsWith('switch:')) continue;
 47	  if (/^code:/.test(key)) {
 48	    // Which key a keycode is depends on the layout; there is no Orca name to check.
 49	    throw new Error(`Hyprland bind "${chord}" is a keycode bind; bind it by keysym so Orca's chords can be checked`);
 50	  }
 51	  const mods = parts.map((p) => MODS[p.toUpperCase()]);
 52	  if (!mods.every(Boolean)) throw new Error(`unknown modifier in Hyprland bind "${chord}"`);
 53	  // Bare keys too: Orca's few bare chords (F7, Delete) can be Hyprland's.
 54	  if (NO_CHORD.has(key.toLowerCase())) continue;
 55	  const n = kb.normalizeKeybindingWithOptions([...mods, KEYS[key.toLowerCase()] ?? key].join('+'), {
 56	    allowBareKeybindings: true,
 57	    allowShiftOnlyKeybindings: true,
 58	  });
 59	  if (!n.ok) {
 60	    throw new Error(`cannot translate Hyprland bind "${chord}" (${n.error}); map its key in KEYS, or NO_CHORD if Orca has none`);
 61	  }
 62	  taken.add(n.value);
 63	  const k = n.value.split('+').pop();
 64	  if (n.value.includes('Shift+') && SHIFTED[k]) taken.add(n.value.replace(/[^+]+$/, SHIFTED[k]));
 65	}
 66	// A digit-index action's one binding stands for its whole 1-9 family.
 67	const isTaken = (id, binding) =>
 68	  kb.isDigitIndexActionId(id)
 69	    ? [1, 2, 3, 4, 5, 6, 7, 8, 9].some((d) => taken.has(binding.replace(/1$/, String(d))))
 70	    : taken.has(binding);
 71	
 72	const overrides = {};
 73	// Actions every one of whose Mac chords Hyprland took: left on Linux defaults.
 74	const fellBack = new Set();
 75	for (const def of kb.KEYBINDING_DEFINITIONS) {
 76	  const mac = kb.getDefaultBindings(def, 'darwin').map((binding) => {
 77	    const cmd = binding.split('+').map((t) => (t === 'Mod' ? 'Cmd' : t)).join('+');
 78	    const n = kb.normalizeKeybindingWithOptions(cmd, kb.normalizeOptionsForAction(def.id));
 79	    if (!n.ok) throw new Error(`${def.id}: ${cmd}: ${n.error}`);
 80	    return n.value;
 81	  });
 82	  const free = mac.filter((b) => !isTaken(def.id, b));
 83	  if (free.length < mac.length) {
 84	    console.error(`${def.id}: ${mac.filter((b) => isTaken(def.id, b)).join(', ')} is Hyprland's`);
 85	  }
 86	  // Every chord taken: leave the action on its Linux default rather than
 87	  // unbinding it. No macOS binding at all is different -- unbound there, so
 88	  // unbound here ([]). Same as the Linux default: nothing to say.
 89	  if (mac.length > 0 && free.length === 0) {
 90	    fellBack.add(def.id);
 91	    continue;
 92	  }
 93	  if (JSON.stringify(free) === JSON.stringify(kb.getDefaultBindings(def, 'linux'))) continue;
 94	  overrides[def.id] = free;
 95	}
 96	
 97	// A fallback can land on a generated chord the Mac table never had to keep
 98	// apart from it. Orca dispatches some actions across scopes, ahead of the
 99	// conflict check's scope groups -- the workspace digits before the tab
100	// digits -- so with Super+1..9 Hyprland's, workspace.selectByIndex stays on
101	// Ctrl+1..9 and the Mac tab.selectByIndex (Ctrl+1..9) would never fire.
102	// Such an action goes back to its own Linux default too, until none is left.
103	const identities = (id, bindings) =>
104	  bindings.flatMap((b) => kb.keybindingConflictIdentities(id, b, 'linux'));
105	for (;;) {
106	  const held = new Set(
107	    [...fellBack].flatMap((id) => identities(id, kb.getDefaultBindings(kb.getKeybindingDefinition(id), 'linux'))),
108	  );
109	  const shadowed = Object.keys(overrides).filter((id) => identities(id, overrides[id]).some((i) => held.has(i)));
110	  if (shadowed.length === 0) break;
111	  for (const id of shadowed) {
112	    console.error(`${id}: ${overrides[id].join(', ')} is a fallen-back Linux default's`);
113	    delete overrides[id];
114	    fellBack.add(id);
115	  }
116	}
117	
118	// Orca drops every action in a conflicting set at load, with only a line in
119	// its diagnostics; fail the build instead.
120	const conflicts = kb.findKeybindingConflicts('linux', overrides);
121	if (conflicts.length > 0) {
122	  throw new Error(`conflicting shortcuts: ${JSON.stringify(conflicts)}`);
123	}
124	process.stdout.write(`${JSON.stringify(overrides, null, 2)}\n`);
  1	// Merges the generated overrides (orca-mac-keybindings.js) into
  2	// ~/.orca/keybindings.json's platforms.linux. See orca.nix.
  3	//
  4	//   node orca-mac-keybindings-merge.js <app>/out/shared <owned.json>
  5	//
  6	// The file is Orca's read-write state, so this owns only what it claimed: a
  7	// sidecar, keybindings.nix-owned.json, maps each claimed action to the value
  8	// it was claimed at -- the value written, or for a key withdrawn in a clash,
  9	// the generated value it would have had. Per key:
 10	//   - claimed, no longer generated, value unchanged: removed;
 11	//   - claimed, value changed since (or the claim withdrawn and a value set):
 12	//     the UI's, left alone;
 13	//   - never claimed but holding a value (no sidecar yet, or newly generated
 14	//     since): the UI's, left alone;
 15	//   - everything else in the file is untouched.
 16	// Then the merged file gets Orca's own conflict check. Orca drops every
 17	// action in a conflicting set at load, so a generated key that clashes with
 18	// a UI shortcut is withdrawn instead, and named, leaving the UI's choice and
 19	// the generated action's Linux default.
 20	const fs = require('fs');
 21	const os = require('os');
 22	const path = require('path');
 23	
 24	// Activation runs under set -e, so a throw here would abandon the rest of
 25	// the switch over a keybinding file. Any failure is one line and exit 0;
 26	// the file is then exactly as it was, since writes only ever rename over it.
 27	process.on('uncaughtException', (e) => {
 28	  console.error(`orca: keybinding merge skipped: ${e.message}`);
 29	  process.exit(0);
 30	});
 31	
 32	const [shared, ownedFile] = process.argv.slice(2);
 33	const kb = require(path.resolve(shared, 'keybindings.js'));
 34	const owned = JSON.parse(fs.readFileSync(ownedFile, 'utf8'));
 35	
 36	const dir = path.join(os.homedir(), '.orca');
 37	const dest = path.join(dir, 'keybindings.json');
 38	const sidecar = path.join(dir, 'keybindings.nix-owned.json');
 39	const isObject = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
 40	const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);
 41	
 42	// Orca's own writer (G$): whole file to a temp name, rename over, and the
 43	// temp removed if either step fails.
 44	function writeJson(file, value) {
 45	  const tmp = `${file}.nix-${process.pid}-${Date.now()}`;
 46	  try {
 47	    fs.writeFileSync(tmp, `${JSON.stringify(value, null, 2)}\n`, { flag: 'wx' });
 48	    fs.renameSync(tmp, file);
 49	  } catch (e) {
 50	    fs.rmSync(tmp, { force: true });
 51	    throw e;
 52	  }
 53	}
 54	
 55	fs.mkdirSync(dir, { recursive: true });
 56	let doc;
 57	if (!fs.existsSync(dest)) {
 58	  doc = { version: 1, keybindings: {}, platforms: { darwin: {}, linux: {}, win32: {} } };
 59	} else {
 60	  let why = null;
 61	  try {
 62	    doc = JSON.parse(fs.readFileSync(dest, 'utf8'));
 63	    if (!isObject(doc)) why = 'not a JSON object';
 64	  } catch (e) {
 65	    why = e.message;
 66	  }
 67	  if (why !== null) {
 68	    // Orca's loader rejects it too and says so; overwriting would lose
 69	    // whatever the user was halfway through editing.
 70	    console.error(`orca: ${dest}: ${why}; leaving it for Orca to report`);
 71	    process.exit(0);
 72	  }
 73	}
 74	
 75	let prev = {};
 76	try {
 77	  const s = JSON.parse(fs.readFileSync(sidecar, 'utf8'));
 78	  if (!isObject(s?.linux)) throw new Error('no .linux object');
 79	  prev = s.linux;
 80	} catch (e) {
 81	  // No sidecar is a first run. A bad one stops the merge: it decides what
 82	  // may be overwritten, and reading it as empty overwrites every key the UI
 83	  // has changed.
 84	  if (e.code !== 'ENOENT') {
 85	    console.error(`orca: ${sidecar}: ${e.message}; not merging -- delete it to start over`);
 86	    process.exit(0);
 87	  }
 88	}
 89	
 90	const platforms = isObject(doc.platforms) ? doc.platforms : {};
 91	const linux = isObject(platforms.linux) ? { ...platforms.linux } : {};
 92	// The UI's: a value on a claimed key that differs from its claim, or any
 93	// value on a key never claimed. Absent (reset in the UI) is not a change --
 94	// the reset target is this table, so it comes back.
 95	const theirs = new Set(
 96	  [...new Set([...Object.keys(prev), ...Object.keys(owned)])].filter(
 97	    (id) => id in linux && (id in prev ? !same(linux[id], prev[id]) : true),
 98	  ),
 99	);
100	for (const id of Object.keys(prev)) {
101	  if (!theirs.has(id)) delete linux[id];
102	}
103	// Every owned key still in the file is the UI's by now (stale ones are
104	// gone), so writing the rest overwrites nothing.
105	const written = {};
106	for (const [id, bindings] of Object.entries(owned)) {
107	  if (theirs.has(id)) continue;
108	  linux[id] = bindings;
109	  written[id] = bindings;
110	}
111	
112	// What Orca's loader feeds its conflict pass: common, then the platform
113	// section over it, with its string shorthand and null/false expanded.
114	// Common is the root's action keys in the legacy shape with no .keybindings.
115	const common = doc.keybindings === undefined ? doc : isObject(doc.keybindings) ? doc.keybindings : {};
116	// Orca's loader (jHn): null/false unbind; a string is a comma list; an array
117	// of strings may hold comma lists too; one bad chord rejects the whole value,
118	// leaving the action on its default (undefined here). Both normalisers return
119	// string[] or {ok:false}.
120	const expand = (id, v) => {
121	  if (v === null || v === false) return [];
122	  const n =
123	    typeof v === 'string' ? kb.normalizeKeybindingListForAction(id, v)
124	      : Array.isArray(v) && v.every((b) => typeof b === 'string') ? kb.normalizeKeybindingArrayForAction(id, v)
125	        : null;
126	  return Array.isArray(n) ? n : undefined;
127	};
128	// Each section parsed on its own, then layered (q$): a bad platform value is
129	// dropped, not allowed to hide a good common one.
130	const parse = (section) =>
131	  Object.fromEntries(
132	    Object.entries(section)
133	      .filter(([id, v]) => kb.isKeybindingActionId(id) && expand(id, v) !== undefined)
134	      .map(([id, v]) => [id, expand(id, v)]),
135	  );
136	const commonParsed = parse(common);
137	const effective = { ...commonParsed, ...parse(linux) };
138	for (;;) {
139	  const withdrawn = kb
140	    .findKeybindingConflicts('linux', effective)
141	    .flatMap((c) => c.actionIds)
142	    .filter((id) => id in written);
143	  // Only generated keys are ever withdrawn. A conflict with none left in it
144	  // -- between UI shortcuts, or a UI shortcut and the Linux default a
145	  // withdrawal brought back -- is Orca's to report.
146	  if (withdrawn.length === 0) break;
147	  for (const id of new Set(withdrawn)) {
148	    console.error(`orca: ${id} ${JSON.stringify(written[id])} clashes with a shortcut set in Orca; keeping that one`);
149	    delete written[id];
150	    delete linux[id];
151	    if (id in commonParsed) effective[id] = commonParsed[id];
152	    else delete effective[id];
153	  }
154	}
155	
156	doc.version = 1;
157	doc.platforms = {
158	  ...platforms,
159	  darwin: isObject(platforms.darwin) ? platforms.darwin : {},
160	  linux,
161	  win32: isObject(platforms.win32) ? platforms.win32 : {},
162	};
163	writeJson(dest, doc);
164	// Every key this table claims, written or withdrawn, at its generated value;
165	// the UI's keep the value last written. Either way a later UI value reads as
166	// changed, the UI's, rather than as never owned and free to overwrite.
167	writeJson(sidecar, {
168	  linux: {
169	    ...owned,
170	    ...Object.fromEntries([...theirs].filter((id) => id in prev).map((id) => [id, prev[id]])),
171	    ...written,
172	  },
173	});

