const kb = require(process.argv[2] + '/keybindings.js');
const m = require(process.argv[2] + '/keybindings/matching.js');
const inp = (key, code, mods) => ({ key, code, meta: mods.includes('m'), control: mods.includes('c'), alt: mods.includes('a'), shift: mods.includes('s') });
const tests = [
  ['Cmd+Shift+Semicolon', inp(':', 'Semicolon', 'ms')],
  ['Cmd+Shift+1', inp('!', 'Digit1', 'ms')],
  ['Cmd+Shift+Plus', inp('+', 'Equal', 'ms')],
  ['Cmd+Shift+Equal', inp('+', 'Equal', 'ms')],
  ['Cmd+Shift+BracketRight', inp('}', 'BracketRight', 'ms')],
  ['Cmd+Shift+Period', inp('>', 'Period', 'ms')],
  ['Cmd+Shift+Slash', inp('?', 'Slash', 'ms')],
  ['Cmd+Shift+Backquote', inp('~', 'Backquote', 'ms')],
];
for (const [b, i] of tests) console.log(b, JSON.stringify(i.key), m.keybindingMatchesInput(b, i, 'linux'));
// every Mac binding with Shift + punctuation/digit
const out = [];
for (const def of kb.KEYBINDING_DEFINITIONS) for (const b of kb.getDefaultBindings(def,'darwin')) if (/Shift/.test(b)) out.push(def.id+':'+b);
console.log(out.join('\n'));
EOF
